/// <summary>
/// AVA/WEN 2024/03/13
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'False positive'),
    FormDataSourceEventHandler(formDataSourceStr(ProdParmReportFinished, ProdParmReportFinished), FormDataSourceEventType::Activated)]
public static void ProdParmReportFinished_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    NoYesId     fromTraverse = false;
    AVATraverseTrans    travTrans;
    ProdParmReportFinished prodParmReportFinished = sender.cursor();

    if (prodParmReportFinished.AVATraverseNum)
    {
        select firstonly travTrans where travTrans.TravNum == prodParmReportFinished.AVATraverseNum
            && travTrans.ProdId == prodParmReportFinished.ProdId;
        if (travTrans.RecId)
        {
            fromTraverse = true;
        }
    }

    sender.formrun().design().controlName(formControlStr(ProdParmReportFinished, AVARegalvanisation)).visible(fromTraverse);

}
